  [ [[v5748eaic9qns]] ] = { t = [[魔法裔与法术环级]], q = [[我能用这个背景特性，把法术的有效环级调整到低于该法术原本（未经调整）的环级吗？]], a = [=[不能。例如，它不能让你把法师的[[火球术]]变成2环法术。]=], book = [[进阶玩家指南]], date = [[2013/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9qns]], cat = [[FAQ]], ai = false, pages = { [[魔法裔]] } },
  [ [[v5748eaic9na9]] ] = { t = [[双重思想与突变次数]], q = [[对于双重思想进化突变（第269页），如果你通过了第二次豁免并改变了形态，这会消耗一次突变能力的使用次数吗？]], a = [[会。实际上，炼金大师是花掉一次突变能力的使用次数，来推翻一次失败的豁免。如果她当天已没有剩余的突变使用次数，就没有多余的次数来启动这次推翻。]], book = [[进阶玩家指南]], date = [[2010/01/09]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9na9]], cat = [[FAQ]], ai = false, pages = { [[炼金大师（进阶职业）]] } },
  [ [[v5748eaic9na8]] ] = { t = [[突变的强制变身与动作]], q = [=[对于突变能力（第268页），如果角色在下一回合无法执行[[标准动作]]，她仍会被迫违背意愿变身吗？如果会，她要用什么动作来变身？]=], a = [=[被迫改变形态是炼金大师所要承担的风险。她不应仅因为下一回合无法执行标准动作（例如处于[[反胃]]状态）就无视这一惩罚。在这种情况下，她必须用掉自己回合中所有可用的动作来变身。例如，处于反胃状态时，她必须用可用的移动动作来突变。如果在触发效应之后的下一回合她只能执行迅捷动作，就必须用该迅捷动作来突变。如果她[[无助]]，则要等到她第一个能执行标准动作（或任何她可用动作）来突变的回合，变身才会发生。

例如，如果她因[[人类定身术]]而无助，她唯一可用的动作就是挣脱的整轮动作。一旦摆脱该法术，在她的下一回合（第一个能执行其他动作的回合），她必须花费一个标准动作来突变。]=], book = [[进阶玩家指南]], date = [[2010/01/09]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9na8]], cat = [[FAQ]], ai = false, pages = { [[炼金大师（进阶职业）]] } },
  [ [[v5748eaic9p1m]] ] = { t = [[防御式突袭的闪避加值]], q = [[盗贼天赋“防御式突袭”（第131页）带来的闪避加值能与自身叠加吗？它对所有人有效，还是只对我攻击的目标有效？]], a = [=[这个盗贼天赋有两个问题。

其一，初印本中它给予的是针对被攻击目标的+1环境加值，是一个很弱的能力。第二次印刷的更新把环境加值改成了闪避加值，却不小心漏掉了“对该生物”这几个字，让它变成了一个很强的能力。

其二，它没有说明闪避加值能否与自身叠加。这在规则中造成了一个奇怪的局面：同一来源的加值本不叠加，而闪避加值却总是叠加。我们尚未对这个天赋做出最终决定，不过倾向于下面的方案：闪避加值只对你[[盗贼#偷袭|偷袭]]的那个生物有效，并且不与自身叠加。这样既防止你通过偷袭一个弱小的生物，来获得对抗强大生物的闪避AC加值，也防止你在同一轮内多次偷袭而把AC堆到离谱的程度。]=], book = [[进阶玩家指南]], date = [[2012/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9p1m]], cat = [[FAQ]], ai = false, pages = { [[防御式突袭]] } },
  [ [[v5748eaic9nk0]] ] = { t = [[启示能否重复选择]], q = [[先知能多次选择同一个启示吗？]], a = [[不能，除非该启示特别说明可以。]], book = [[进阶玩家指南]], date = [[2010/01/12]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9nk0]], cat = [[FAQ]], ai = false, pages = { [[先知]] } },
  [ [[v5748eaic9qlk]] ] = { t = [[先知与感知相关的牧师法术]], q = [=[对于使用感知的牧师法术和效果（比如[[灵能武器]]），我能改用魅力调整值吗？]=], a = [[按文字所写，这些效果说的是“感知”（因为它们写成时，还没有以魅力为施法属性的先知职业这个构想），因此先知必须使用她的感知调整值。

不过，允许先知对提到施法者感知调整值（或加值）的牧师法术使用她的魅力调整值（或加值），是一条完全合理的房规。]], book = [[进阶玩家指南]], date = [[2013/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9qlk]], cat = [[FAQ]], ai = false, pages = { [[先知]], [[灵能武器]] } },
